import numpy as np


class DiffPool:
    """Differentiable graph pooling."""

    def __init__(self, input_dim, num_clusters):
        self.W_assign = np.random.randn(input_dim, num_clusters) * 0.01
        self.W_embed = np.random.randn(input_dim, input_dim) * 0.01

    def compute_assignment(self, X):
        logits = X @ self.W_assign
        S = np.exp(logits - np.max(logits, axis=1, keepdims=True))
        S = S / S.sum(axis=1, keepdims=True)
        return S

    def pool_features(self, S, X):
        return S.T @ X

    def pool_adjacency(self, S, A):
        return S.T @ A @ S

    def link_pred_loss(self, S, A):
        A_rec = S @ S.T
        A_rec = np.clip(A_rec, 1e-7, 1 - 1e-7)
        loss = -np.mean(A * np.log(A_rec) + (1 - A) * np.log(1 - A_rec))
        return loss

    def entropy_loss(self, S):
        eps = 1e-8
        return -np.sum(S * np.log(S + eps)) / (S.shape[0] * S.shape[1])
